// Persists FoodOS jdbc order dao data through JDBC.
// Keeps SQL access and row mapping behind the DAO boundary.

package com.foodapp.dao;

import com.foodapp.model.*;
import java.sql.*;
import java.util.ArrayList;
import java.util.List;

public class JdbcOrderDao implements OrderDao {
    @Override public long createOrder(Connection connection, long customerId, long restaurantId, long addressId, java.math.BigDecimal subtotal, java.math.BigDecimal discount, java.math.BigDecimal deliveryFee, java.math.BigDecimal total) throws SQLException { String sql = "INSERT INTO orders(customer_id, restaurant_id, address_id, subtotal, discount_amount, delivery_fee, total_amount) VALUES (?, ?, ?, ?, ?, ?, ?)"; try (PreparedStatement statement = connection.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) { statement.setLong(1, customerId); statement.setLong(2, restaurantId); statement.setLong(3, addressId); statement.setBigDecimal(4, subtotal); statement.setBigDecimal(5, discount); statement.setBigDecimal(6, deliveryFee); statement.setBigDecimal(7, total); statement.executeUpdate(); try (ResultSet keys = statement.getGeneratedKeys()) { if (!keys.next()) throw new SQLException("Order id was not generated"); return keys.getLong(1); } } }
    @Override public void addOrderItem(Connection connection, long orderId, long itemId, int quantity, java.math.BigDecimal price) throws SQLException { try (PreparedStatement statement = connection.prepareStatement("INSERT INTO order_items(order_id, item_id, quantity, unit_price) VALUES (?, ?, ?, ?)")) { statement.setLong(1, orderId); statement.setLong(2, itemId); statement.setInt(3, quantity); statement.setBigDecimal(4, price); statement.executeUpdate(); } }
    @Override public void createPayment(Connection connection, long orderId, PaymentMethod method, java.math.BigDecimal amount) throws SQLException { try (PreparedStatement statement = connection.prepareStatement("INSERT INTO payments(order_id, method, amount, status, paid_at) VALUES (?, ?, ?, 'SUCCESS', CURRENT_TIMESTAMP)")) { statement.setLong(1, orderId); statement.setString(2, method.name()); statement.setBigDecimal(3, amount); statement.executeUpdate(); } }
    @Override public List<OrderSummary> findByCustomer(Connection connection, long customerId) throws SQLException { String sql = "SELECT o.order_id, r.name, o.order_date, o.status, o.total_amount FROM orders o JOIN restaurants r ON r.restaurant_id = o.restaurant_id WHERE o.customer_id = ? ORDER BY o.order_date DESC"; try (PreparedStatement statement = connection.prepareStatement(sql)) { statement.setLong(1, customerId); List<OrderSummary> orders = new ArrayList<>(); try (ResultSet result = statement.executeQuery()) { while (result.next()) orders.add(new OrderSummary(result.getLong(1), result.getString(2), result.getTimestamp(3).toLocalDateTime(), OrderStatus.valueOf(result.getString(4)), result.getBigDecimal(5))); } return orders; } }
    @Override public OrderDetail findDetail(Connection connection, long customerId, long orderId) throws SQLException { String header = "SELECT o.order_id, r.name, o.order_date, o.status, o.subtotal, o.discount_amount, o.delivery_fee, o.total_amount FROM orders o JOIN restaurants r ON r.restaurant_id = o.restaurant_id WHERE o.customer_id = ? AND o.order_id = ?"; try (PreparedStatement statement = connection.prepareStatement(header)) { statement.setLong(1, customerId); statement.setLong(2, orderId); try (ResultSet result = statement.executeQuery()) { if (!result.next()) return null; OrderDetail detail = new OrderDetail(result.getLong(1), result.getString(2), result.getTimestamp(3).toLocalDateTime(), OrderStatus.valueOf(result.getString(4)), result.getBigDecimal(5), result.getBigDecimal(6), result.getBigDecimal(7), result.getBigDecimal(8), lines(connection, orderId)); return detail; } } }
    private List<OrderDetail.OrderLine> lines(Connection connection, long orderId) throws SQLException { String sql = "SELECT mi.name, oi.quantity, oi.unit_price, oi.line_total FROM order_items oi JOIN menu_items mi ON mi.item_id = oi.item_id WHERE oi.order_id = ? ORDER BY oi.order_item_id"; try (PreparedStatement statement = connection.prepareStatement(sql)) { statement.setLong(1, orderId); List<OrderDetail.OrderLine> lines = new ArrayList<>(); try (ResultSet result = statement.executeQuery()) { while (result.next()) lines.add(new OrderDetail.OrderLine(result.getString(1), result.getInt(2), result.getBigDecimal(3), result.getBigDecimal(4))); } return lines; } }
}
